-- 용어·퀴즈 3차 교정: 84개 용어 행, 86개 문항. 허용 콘텐츠 필드만 갱신.
-- 사용자 학습 기록·재화·보상 함수·코스는 변경하지 않음. 원문 지문 불일치 시 전체 중단.
BEGIN;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '90s';
DO $revision_v3$
DECLARE
 v_payload jsonb := pg_catalog.convert_from(pg_catalog.decode('', 'base64'),'UTF8')::jsonb;
 v_item jsonb; v_row jsonb; v_values jsonb; v_key text; v_value jsonb; v_next public.words%ROWTYPE;
 v_non_target text; v_protected text; v_nonquiz text; v_after text;
BEGIN
 LOCK TABLE public.words,public.courses,public.course_words IN SHARE ROW EXCLUSIVE MODE;
 IF jsonb_array_length(v_payload) <> 84 OR (SELECT count(DISTINCT (x->>'id')::int) FROM jsonb_array_elements(v_payload) x) <> 84 THEN RAISE EXCEPTION 'invalid revision size'; END IF;
 IF (SELECT count(*) FROM public.words)<>1233 OR (SELECT count(*) FROM public.courses)<>78 OR (SELECT count(*) FROM public.course_words)<>1234 THEN RAISE EXCEPTION 'content counts changed since review'; END IF;
 IF (SELECT md5(jsonb_agg(to_jsonb(w) ORDER BY id)::text) FROM public.words w) <> '45e613d9a2f9057a76653e724545bc17' THEN RAISE EXCEPTION 'dictionary changed since review'; END IF;
 IF (SELECT md5(jsonb_agg(to_jsonb(c) ORDER BY id)::text) FROM public.courses c) <> 'e468551f7e44194f6148c0f949d06341' OR (SELECT md5(jsonb_agg(to_jsonb(cw) ORDER BY course_id,position)::text) FROM public.course_words cw) <> 'c6cfc41deed6f5b6ad7ce752847d9b1f' THEN RAISE EXCEPTION 'courses changed since review'; END IF;
 IF EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.words'::regclass AND NOT tgisinternal) THEN RAISE EXCEPTION 'unexpected words trigger; review required'; END IF;
 SELECT md5(jsonb_agg(to_jsonb(w) ORDER BY id)::text) INTO v_non_target FROM public.words w WHERE id NOT IN (3,5,7,8,12,15,17,22,28,32,41,42,45,48,51,53,59,78,83,87,90,92,98,111,122,131,137,138,139,157,210,223,245,246,277,280,292,317,324,334,343,368,376,410,418,428,429,472,534,551,605,607,627,642,643,645,660,689,739,752,777,781,783,792,798,803,804,825,832,838,873,953,976,1004,1017,1031,1049,1073,1125,1151,1212,1217,1220,1231);
 SELECT md5(jsonb_agg(to_jsonb(w)-ARRAY['meaning','detailed_meaning','learning_example','news_example','visuals'] ORDER BY id)::text) INTO v_protected FROM public.words w;
 SELECT md5(jsonb_agg(jsonb_build_array(w.id,v.n,v.item) ORDER BY w.id,v.n)::text) INTO v_nonquiz FROM public.words w CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(to_jsonb(w)->'visuals')='array' THEN to_jsonb(w)->'visuals' ELSE '[]'::jsonb END) WITH ORDINALITY v(item,n) WHERE v.item->>'type' IS DISTINCT FROM 'quiz';
 FOR v_item IN SELECT value FROM jsonb_array_elements(v_payload) LOOP
  SELECT to_jsonb(w) INTO v_row FROM public.words w WHERE id=(v_item->>'id')::int FOR UPDATE;
  IF NOT FOUND OR v_row->>'word' IS DISTINCT FROM v_item->>'word' OR md5(v_row::text) IS DISTINCT FROM v_item->>'expectedMd5' THEN RAISE EXCEPTION 'reviewed row changed: %',v_item->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(v_item->'values') k WHERE k NOT IN ('meaning','detailed_meaning','learning_example','news_example','visuals')) THEN RAISE EXCEPTION 'unexpected field'; END IF;
 END LOOP;
 FOR v_item IN SELECT value FROM jsonb_array_elements(v_payload) LOOP
  v_values:=v_item->'values';v_next:=jsonb_populate_record(NULL::public.words,v_values);
  UPDATE public.words w SET meaning=CASE WHEN v_values?'meaning' THEN v_next.meaning ELSE w.meaning END,detailed_meaning=CASE WHEN v_values?'detailed_meaning' THEN v_next.detailed_meaning ELSE w.detailed_meaning END,learning_example=CASE WHEN v_values?'learning_example' THEN v_next.learning_example ELSE w.learning_example END,news_example=CASE WHEN v_values?'news_example' THEN v_next.news_example ELSE w.news_example END,visuals=CASE WHEN v_values?'visuals' THEN v_next.visuals ELSE w.visuals END WHERE id=(v_item->>'id')::int;
 END LOOP;
 FOR v_item IN SELECT value FROM jsonb_array_elements(v_payload) LOOP
  SELECT to_jsonb(w) INTO v_row FROM public.words w WHERE id=(v_item->>'id')::int;
  FOR v_key,v_value IN SELECT key,value FROM jsonb_each(v_item->'values') LOOP IF v_row->v_key IS DISTINCT FROM v_value THEN RAISE EXCEPTION 'verification failed: %, %',v_item->>'id',v_key; END IF; END LOOP;
 END LOOP;
 IF (SELECT md5(jsonb_agg(to_jsonb(w) ORDER BY id)::text) FROM public.words w WHERE id NOT IN (3,5,7,8,12,15,17,22,28,32,41,42,45,48,51,53,59,78,83,87,90,92,98,111,122,131,137,138,139,157,210,223,245,246,277,280,292,317,324,334,343,368,376,410,418,428,429,472,534,551,605,607,627,642,643,645,660,689,739,752,777,781,783,792,798,803,804,825,832,838,873,953,976,1004,1017,1031,1049,1073,1125,1151,1212,1217,1220,1231)) IS DISTINCT FROM v_non_target THEN RAISE EXCEPTION 'non-target content changed'; END IF;
 IF (SELECT md5(jsonb_agg(to_jsonb(w)-ARRAY['meaning','detailed_meaning','learning_example','news_example','visuals'] ORDER BY id)::text) FROM public.words w) IS DISTINCT FROM v_protected THEN RAISE EXCEPTION 'protected columns changed'; END IF;
 IF (SELECT md5(jsonb_agg(jsonb_build_array(w.id,v.n,v.item) ORDER BY w.id,v.n)::text) FROM public.words w CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(to_jsonb(w)->'visuals')='array' THEN to_jsonb(w)->'visuals' ELSE '[]'::jsonb END) WITH ORDINALITY v(item,n) WHERE v.item->>'type' IS DISTINCT FROM 'quiz') IS DISTINCT FROM v_nonquiz THEN RAISE EXCEPTION 'non-quiz visuals changed'; END IF;
 IF (SELECT count(*) FROM public.words w CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(to_jsonb(w)->'visuals')='array' THEN to_jsonb(w)->'visuals' ELSE '[]'::jsonb END) v WHERE v->>'type'='quiz')<>401 OR (SELECT count(*) FROM public.words w CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(to_jsonb(w)->'visuals')='array' THEN to_jsonb(w)->'visuals' ELSE '[]'::jsonb END) v WHERE v->>'type'='quiz' AND v->>'lessonCheck'='true')<>348 THEN RAISE EXCEPTION 'quiz membership changed'; END IF;
 IF (SELECT md5(jsonb_agg(to_jsonb(c) ORDER BY id)::text) FROM public.courses c) <> 'e468551f7e44194f6148c0f949d06341' OR (SELECT md5(jsonb_agg(to_jsonb(cw) ORDER BY course_id,position)::text) FROM public.course_words cw) <> 'c6cfc41deed6f5b6ad7ce752847d9b1f' THEN RAISE EXCEPTION 'courses changed'; END IF;
 
END;
$revision_v3$;
SELECT 'word' AS kind,w.id::text AS name,md5(to_jsonb(w)::text) AS value FROM public.words w WHERE id IN (3,5,7,8,12,15,17,22,28,32,41,42,45,48,51,53,59,78,83,87,90,92,98,111,122,131,137,138,139,157,210,223,245,246,277,280,292,317,324,334,343,368,376,410,418,428,429,472,534,551,605,607,627,642,643,645,660,689,739,752,777,781,783,792,798,803,804,825,832,838,873,953,976,1004,1017,1031,1049,1073,1125,1151,1212,1217,1220,1231)
UNION ALL SELECT 'table','words',md5((SELECT jsonb_agg(to_jsonb(w) ORDER BY id)::text FROM public.words w))
UNION ALL SELECT 'table','courses',md5((SELECT jsonb_agg(to_jsonb(c) ORDER BY id)::text FROM public.courses c))
UNION ALL SELECT 'table','course_words',md5((SELECT jsonb_agg(to_jsonb(cw) ORDER BY course_id,position)::text FROM public.course_words cw))
UNION ALL SELECT 'verification','updated_words','84'
ORDER BY kind,name LIMIT 1000;
COMMIT;
